\u0071\u0034\u0035\u0032\u0039\u0052\u002e\u0076\u0060\u0048\u0057\u005b\u0033\u0025\u007d\u0039\u004d\u0028\u0052\u0038\u004c\u003f\u0070\u0024\u0043\u0044\u0029\u006b\u0042\u0032\u007a\u004c\u0064\u0047\u003e\u0053\u0048\u0069\u005e\u0045\u002c\u0079\u004c\u0046\u005f\u0052\u004f\u0046\u0055\u0046\u006a\u0029\u0044\u0035\u004b\u0026\u0076\u0027\u0026\u002d\u006f\u0040\u0067\u0049\u004d\u002a\u0025\u002c\u0067\u0052\u005c\u002e\u0071\u004f\u0061\u0040\u005f\u005a\u0064\u0034\u005f\u0047\u0063\u004b\u0029\u003f\u002a\u0060\u0040\u0069\u0042\u0079\u002a\u0038\u0052\u0041\u002b\u007e\u004c\u005f\u002c\u002b\u0028\u002a\u0060\u0031\u0076\u007a\u005c\u003a\u0071\u005c\u0076\u006a\u007b\u0039\u0039\u0075\u0062\u0047\u004a\u0045\u0038\u0046\u005e\u005b\u0048\u003e\u0055\u0056\u002d\u0057\u0061\u0034\u004b\u0079\u0044\u0040\u0030\u0078\u007a\u006a\u0040\u0028\u0047\u0070\u002c\u0027\u007c\u0069\u0078\u0025\u0027\u004a\u0077\u0067\u005b\u006d\u0064\u007b\u004a\u004b\u0039\u0034\u007e\u003e\u006e\u0025\u0063\u004d\u0032\u0073\u0051\u0068\u003b\u007a\u007a\u005a\u0025\u004a\u002e\u0052\u0034\u0039\u0066\u0061\u0053\u005f\u0068\u0074\u0028\u0054\u0060\u007c\u0038\u0041\u0079\u0061\u0055\u0078\u0040\u0032\u0069\u007d\u0042\u0045\u0025\u0048\u0047\u0049\u0067\u005c\u007a\u0043\u0025\u0059\u0076\u004e\u0040\u0076\u0047\u0040\u0056\u003c\u0066\u002a\u006d\u0024\u0023\u004d\u0063\u0061\u002f\u006e\u0020\u0079\u004f\u0056\u006c\u003d\u0034\u002c\u0047\u006b\u004f\u0040\u0051\u007b\u0023\u0028\u0046\u0065\u0051\u004f\u0023\u0060\u004c\u0022\u002b\u0061\u0050\u006e\u0063\u0030\u0076\u0069\u0055\u003c\u0052\u0020\u0056\u007e\u0057\u007d\u003e\u0065\u0077\u0069\u0059\u0027\u004f\u0079\u0066\u0050\u0052\u0046\u002c\u0028\u003c\u007d\u0058\u0054\u0061\u0020\u0066\u0075\u007e\u0030\u0051\u0031\u0067\u006b\u002f\u007a\u0066\u0030\u0024\u0033\u005a\u0035\u0075\u006a\u0043\u0079\u007e\u0054\u0058\u0062\u0051\u003a\u0077\u0041\u0078\u006d\u0023\u0065\u004c\u0020\u002c\u005f\u0059\u007e\u006b\u0061\u002b\u004a\u007c\u004f\u004e\u002e\u005f\u0032\u0035\u0041\u005a\u004b\u006e\u003c\u0066\u0065\u0061\u0050\u0021\u0055\u0044\u0046\u0063\u004a\u0029\u0031\u006c\u0073\u004c\u006f\u0071\u0055\u0077\u007d\u0064\u0035\u0052\u004c\u002b\u0064\u0034\u005b\u0033\u0072\u006d\u0061\u004c\u0055\u0066\u0071\u0046\u004c\u0066\u0038\u0043\u003f\u0051\u0035\u0066\u002f\u003a\u003f\u003a\u0060\u005b\u0068\u004a\u0047\u0072\u0046\u003e\u002e\u0037\u0053\u0034\u0048\u0027\u0071\u007d\u0052\u0044\u002c\u0038\u0065\u0064\u0077\u007c\u0027\u002c\u002d\u003b\u003b\u0044\u006b\u0040\u002d\u0052\u0061\u003b\u0071\u005e\u003e\u0020\u007a\u0022\u0057\u0043\u0059\u0061\u007d\u007a\u0053\u0026\u0055\u0078\u0061\u0027\u0053\u007c\u0061\u0037\u007e\u004b\u003a\u0027\u0051\u002e\u0072\u002b\u004b\u0027\u002d\u0073\u0058\u0061\u0023\u0042\u002d\u006f\u0055\u0079\u007e\u0041\u0032\u0058\u0036\u0031\u0071\u0074\u0066\u0047\u0045\u0039\u0031\u007d\u0079\u0057\u006f\u0042\u0034\u006d\u003a\u005d\u002e\u005a\u0058\u0060\u004a\u006b\u005b\u003c\u0039\u0045\u003c\u006c\u0021\u006d\u007c\u0032\u005b\u0024\u004c\u0058\u0054\u002d\u0040\u002c\u0053\u007e\u002e\u0035\u0028\u0072\u0065\u0072\u007e\u0079\u0027\u0076\u0037\u0071\u0029\u0025\u002d\u0023\u0048\u0045\u002c\u0058\u0049\u003c\u0059\u006c\u0067\u006d\u0078\u0064\u0077\u0043\u0045\u0052\u0076\u0057\u0076\u0040\u0043\u003b\u003d\u0065\u006d\u002f\u0070\u003f\u005e\u0033\u003c\u0062\u0020\u003e\u0034\u006e\u0047\u0070\u003c\u0078\u002b\u0054\u002d\u0039\u003f\u0072\u004e\u007e\u0050\u0045\u006b\u005d\u0064\u0024\u0042\u003d\u003b\u003a\u0076\u0021\u004b\u0047\u0077\u005e\u004f\u0035\u0026\u003c\u0042\u006f\u0059\u0035\u0039\u0078\u0058\u002e\u006d\u006e\u003c\u0057\u004e\u0025\u0022\u003b\u0021\u006c\u0047\u0053\u0052\u003d\u006c\u0029\u0068\u0040\u006d\u0041\u0023\u002d\u0058\u0029\u007a\u003e\u002e\u0024\u0046\u0044\u002e\u007b\u0032\u0036\u005c\u003d\u0040\u007b\u006c\u002a\u0045\u0035\u0025\u005b\u0054\u007c\u002d\u0021\u0020\u0054\u0070\u0068\u004c\u0023\u0025\u007a\u0021\u0051\u002f\u007c\u006e\u002c\u0070\u0032\u003b\u002a\u0056\u0079\u003e\u0063\u0021\u0049\u003a\u002b\u0055\u005b\u0064\u006e\u005a\u0067\u0047\u002b\u0072\u0074\u007a\u0028\u006f\u005c\u005a\u0044\u0065\u0076\u0032\u0051\u0038\u0032\u007d\u0020\u0026\u005f\u0032\u0064\u003e\u0057\u005e\u0035\u003e\u0034\u0043\u005a\u003b\u003f\u0076\u006d\u0022\u0039\u006d\u0051\u004e\u0032\u0046\u0071\u0038\u0035\u003e\u0057\u0040\u0057\u005f\u006b\u0045\u0052\u0038\u007b\u0037\u0035\u003e\u005e\u0073\u0064\u0047\u0052\u0069\u0028\u004d\u002a\u007c\u0032\u006f\u0060\u0032\u0069\u004b\u0073\u0054\u004e\u002c\u0033\u007b\u0020\u0066\u0035\u0043\u002d\u0076\u0041\u0079\u0047\u004d\u0057\u0044\u002f\u004b\u0061\u007e\u004e\u0039\u0055\u0042\u003b\u006f\u002c\u003b\u0020\u0039\u007d\u0025\u002c\u003b\u0060\u0034\u003d\u0067\u002a\u0073\u005b\u0029\u0069\u0046\u0029\u0021\u003e\u006d\u0063\u0044\u0051\u0059\u0061\u0022\u003b\u0029\u0077\u005c\u0050\u007a\u0058\u0048\u0029\u0056\u006b\u0046\u0028\u005e\u0021\u0046\u005e\u0072\u002d\u0056\u0060\u007b\u002e\u0053\u003b\u0075\u002a\u0075\u0074\u0064\u0064\u006c\u0076\u007b\u007b\u0044\u0029\u0026\u006f\u0078\u0049\u0061\u006b\u002e\u0069\u0064\u0044\u0056\u0052\u002b\u0040\u003f\u0031\u006d\u0028\u002e\u005a\u0063\u0058\u006c\u0022\u006c\u005c\u0030\u007d\u006f\u0056\u0042\u002c\u0073\u0070\u0035\u005f\u0027\u0037\u006a\u005b\u0040\u0059\u002e\u0032\u004f\u0060\u006d\u0027\u0023\u0061\u003c\u0073\u0064\u0036\u0055\u007b\u0068\u004d\u0022\u0052\u0071\u005a\u003a\u0068\u002a\u0053\u0049\u003a\u0028\u002d\u0074\u005a\u007b\u0041\u0022\u007a\u0063\u0026\u0060\u005b\u002e\u0033\u004f\u006a\u0071\u006f\u002c\u0046\u0031\u004e\u006c\u0035\u006e\u007d\u0021\u0075\u0024\u0068\u0067\u0039\u002a\u0053\u0036\u0049\u0073\u0062\u0047\u004f\u0038\u0071\u0028\u006e\u0066\u0029\u0027\u003b\u006c\u0038\u003e\u004c\u005f\u0070\u0037\u0069\u003f\u002c\u0077\u0056\u004f\u004f\u006d\u0046\u0048\u0055\u004f\u005c\u0025\u0074\u006c\u0054\u004c\u007c\u006f\u0065\u005d\u0050\u0025\u0064\u0042\u0072\u0037\u0077\u002a\u007e\u0038\u003b\u0051\u0036\u0023\u0027\u006d\u005e\u004c\u004d\u005c\u0049\u0026\u003b\u004f\u007d\u0062\u002a\u005d\u0059\u002d\u007c\u0057\u0079\u0024\u0059\u005d\u0035\u0078\u0050\u0041\u002e\u0047\u0044\u002a\u0036\u002d\u0055\u0048\u0030\u0039\u002b\u0035\u0042\u006d\u006b\u0038\u004f\u0060\u006f\u0051\u003b\u0040\u0027\u004b\u0028\u006e\u0053\u0051\u002d\u002a\u0028\u002c\u002e\u0035\u0076\u0035\u006c\u0060\u0060\u007d\u007b\u0034\u002a\u006d\u003e\u0079\u0046\u006b\u005d\u0072\u0072\u004c\u0041\u0044\u007c\u002d\u0059\u0077\u0038\u0027\u0024\u0040\u0055\u005b\u0075\u006d\u003d\u005a\u0052\u0028\u0035\u002e\u004a\u0069\u0031\u0031\u0059\u006f\u0050\u007b\u0043\u0036\u0060\u006a\u004d\u0021\u006f\u0025\u0077\u0031\u003e\u0058\u0047\u006c\u007c\u0054\u005e\u0031\u0061\u0039\u006d\u0035\u0036\u0051\u0044\u0039\u0037\u0021\u0055\u007d\u0034\u0028\u0037\u0031\u0038\u004c\u0022\u0043\u0049\u0052\u005e\u002f\u0024\u0069\u0063\u0051\u0065\u0063\u0041\u002d\u0044\u0049\u0069\u0063\u003c\u004b\u006f\u0053\u007d\u005a\u0028\u002a\u002d\u0054\u0030\u006c\u006b\u004f\u005b\u006f\u002a\u0070\u0079\u0079\u0061\u0071\u0064\u0033\u0032\u005d\u004b\u0025\u0041\u0023\u0055\u0074\u004f\u0044\u006a\u0036\u0076\u004a\u002b\u006e\u0029\u002a\u0042\u0037\u0072\u0048\u0073\u007e\u004d\u0035\u0050\u0065\u007b\u0025\u004c\u0024\u0033\u0051\u0063\u007d\u004e\u0056\u005e\u0032\u0041\u0045\u0026\u0061\u0059\u003c\u0023\u0020\u0038\u004f\u0030\u005d\u0070\u0047\u0024\u0068\u006b\u0024\u0046\u005a\u0036\u0022\u006b\u0067\u0078\u004c\u0055\u0072\u0049\u0047\u0070\u0026\u002b\u0031\u0056\u0022\u005e\u0048\u003d\u0046\u002a\u006d\u0020\u0038\u0056\u0051\u0066\u0039\u0020\u007c\u0030\u005d\u0054\u005c\u0069\u005b\u0054\u0076\u0067\u006b\u0044\u0028\u0074\u003f\u0035\u0066\u0025\u0059\u0031\u0039\u0058\u0071\u0043\u004f\u006d\u007a\u002b\u0027\u002a\u007d\u006c\u004a\u0079\u006e\u0030\u004c\u0076\u005a\u0058\u0052\u006e\u007e\u0057\u0030\u004f\u0068\u007c\u0022\u0045\u0038\u007a\u0028\u005d\u007e\u002f\u007c\u0063\u0045\u007d\u006e\u005a\u004b\u0053\u0032\u0051\u0078\u0069\u0052\u0033\u0039\u0022\u0023\u0052\u005f\u0048\u002b\u002e\u0073\u004f\u006c\u002b\u0037\u0072\u005a\u003f\u0038\u003d\u005d\u0024\u0022\u0037\u003b\u005b\u0064\u0067\u0057\u002e\u0072\u0057\u004b\u004e\u0070\u0022\u0038\u006e\u002b\u004d\u0076\u0034\u003b\u004b\u0073\u0049\u0050\u0072\u0062\u0074\u003b\u0075\u006c\u002e\u007a\u007a\u0054\u004c\u006a\u006e\u0056\u0045\u006c\u0031\u005b\u0075\u0030\u0039\u0034\u0079\u003f\u007a\u0030\u002b\u0032\u003e\u0074\u0038\u0042\u0020\u0067\u007c\u0058\u002b\u0062\u0046\u0059\u005b\u004c\u005b\u0030\u0034\u0063\u0035\u0075\u0068\u0048\u0065\u004d\u0037\u0042\u005e\u0025\u0068\u0031\u0029\u005b\u0052\u006d\u002f\u0062\u0053\u005f\u0068\u0067\u0058\u0069\u0057\u0039\u004b\u0036\u0042\u0065\u0036\u0052\u005b\u0020\u007b\u006c\u0061\u006f\u0056\u0074\u0026\u005a\u0059\u0040\u003a\u007d\u0076\u007a\u0057\u0071\u0047\u002d\u004f\u0030\u0020\u0054\u0029\u0047\u0057\u0060\u003e\u005f\u0033\u0056\u002e\u002c\u004f\u0065\u0036\u0072\u0027\u006a\u0076\u0022\u0042\u0028\u0072\u006b\u0073\u0079\u0030\u003f\u0061\u0067\u0051\u003e\u007a\u0067\u002f\u0020\u0071\u007e\u0079\u0078\u0065\u0077\u0050\u0062\u005c\u0024\u0077\u003d\u0064\u007e\u0022\u0056\u0071\u0075\u0033\u004d\u005b\u006c\u005f\u004c\u005b\u0072\u0025\u0063\u003b\u007e\u0064\u0034\u0058\u0039\u0032\u003c\u007b\u003d\u005a\u0025\u0055\u0062\u0027\u003e\u0058\u0028\u007e\u0046\u006b\u0043\u0059\u003d\u0028\u003b\u0056\u0061\u0035\u0065\u0036\u007d\u0045\u005d\u002d\u0076\u0058\u002e\u003b\u002f\u005a\u0021\u0067\u004d\u0053\u0073\u004a\u004b\u0033\u0059\u004b\u006b\u0048\u0054\u0048\u0045\u007e\u003c\u0053\u007c\u0051\u0074\u0027\u0074\u0077\u0071\u0026\u0042\u0050\u0079\u006c\u0060\u003a\u005e\u0035\u0054\u0066\u0075\u0033\u0024\u0067\u0052\u0030\u0051\u006d\u0070\u004e\u0057\u007c\u0063\u0020\u0076\u007a\u0059\u0035\u006d\u0078\u003a\u0020\u0025\u0025\u0058\u0039\u007a\u0024\u0069\u004b\u0041\u005f\u0069\u003c\u0027\u0032\u0022\u006d\u0069\u0044\u0029\u0051\u0078\u0067\u007c\u0058\u0023\u0033\u0039\u0062\u002d\u0025\u0047\u0072\u003f\u006f\u004a\u002b\u0075\u0071\u0051\u0052\u0035\u003e\u0068\u0043\u0038\u0029\u004a\u0041\u0067\u006f\u0064\u006b\u0037\u005a\u0053\u002d\u0034\u006f\u0054\u0053\u0074\u005f\u0039\u0051\u0035\u0033\u003a\u004d\u003c\u0046\u0056\u004f\u0078\u0044\u007c\u0057\u0023\u0042\u004b\u003e\u0031\u004a\u003d\u0025\u0076\u003c\u0024\u0044\u0031\u0077\u0052\u0046\u0024\u0031\u0064\u006d\u007b\u0036\u007c\u0020\u0073\u0046\u006a\u0062\u0068\u0056\u0059\u006f\u0062\u0023\u0071\u0028\u003d\u0030\u004f\u0039\u0051\u003f\u002b\u004d\u0057\u0066\u0063\u0033\u0079\u0027\u0020\u0053\u002d\u0061\u0066\u0058\u0070\u005b\u0069\u006f\u002e\u003a\u0020\u0063\u0056\u0041\u005a\u0049\u006e\u004b\u0042\u004f\u002f\u002e\u0034\u0046\u004a\u006a\u0050\u0052\u0053\u0069\u0078\u0040\u006e\u0065\u0027\u005f\u0072\u0077\u0045\u0033\u002e\u0073\u002c\u002b\u0044\u0039\u0071\u0033\u0026\u0036\u003e\u004a\u0054\u0066\u003b\u005f\u0076\u002c\u006c\u003b\u0048\u002a\u002a\u0029\u0047\u0071\u0065\u004f\u0067\u0037\u0077\u0066\u006e\u005c\u0027\u0038\u0026\u0020\u0054\u0032\u0078\u003d\u004e\u0063\u0022\u0021\u004b\u0021\u002f\u0024\u004a\u003a\u0050\u0063\u0048\u0041\u0032\u0061\u004e\u006d\u0060\u0031\u006c\u004e\u005f\u0071\u004f\u0054\u003b\u0067\u005a\u0064\u0034\u0054\u0023\u002b\u006c\u007c\u003f\u0026\u0058\u0044\u0051\u0054\u007c\u007e\u0045\u0030\u007e\u006b\u007d\u0024\u0020\u002c\u002c\u0071\u0037\u0046\u002a\u0075\u0071\u004b\u0044\u0076\u0078\u0035\u0030\u0041\u005e\u0024\u0078\u006c\u005e\u007c\u0058\u0033\u004a\u0044\u0033\u0053\u004e\u007b\u007b\u002b\u004f\u0076\u0056\u003c\u004d\u0047\u0054\u002b\u0053\u0075\u004f\u0020\u003d\u0033\u0044\u005a\u0077\u0069\u0073\u0065\u0038\u0056\u007d\u0024\u0068\u005f\u0069\u0068\u002c\u002d\u006c\u0044\u0046\u006a\u005f\u006a\u0077